dockerCompose:
version: '3.8'

services:
  hermes:
    image: ghcr.io/nousresearch/hermes:latest
    container_name: {{PROJECT_NAME}}-hermes
    restart: unless-stopped
    ports:
      - "{{HOST_PORT}}:8000"
    environment:
      - HERMES_HOST=0.0.0.0
      - HERMES_PORT=8000
      - HERMES_LOG_LEVEL={{LOG_LEVEL}}
      - HERMES_DB_PATH=/app/data/hermes.db
      - HERMES_SKILLS_PATH=/app/skills
      - HERMES_PROFILE={{PROFILE}}
      - LLM_PROVIDER={{LLM_PROVIDER}}
      - LLM_API_KEY={{LLM_API_KEY}}
      - LLM_MODEL={{LLM_MODEL}}
      - EMBEDDING_PROVIDER={{EMBEDDING_PROVIDER}}
      - EMBEDDING_API_KEY={{EMBEDDING_API_KEY}}
      - EMBEDDING_MODEL={{EMBEDDING_MODEL}}
      - TELEGRAM_BOT_TOKEN={{TELEGRAM_BOT_TOKEN}}
      - TELEGRAM_CHAT_ID={{TELEGRAM_CHAT_ID}}
      - DISCORD_BOT_TOKEN={{DISCORD_BOT_TOKEN}}
      - DISCORD_CLIENT_ID={{DISCORD_CLIENT_ID}}
      - SLACK_BOT_TOKEN={{SLACK_BOT_TOKEN}}
      - SLACK_SIGNING_SECRET={{SLACK_SIGNING_SECRET}}
      - WHATSAPP_SESSION_PATH=/app/data/whatsapp
      - MCP_SERVERS={{MCP_SERVERS}}
    volumes:
      - hermes_data:/app/data
      - hermes_skills:/app/skills
    healthcheck:
      test: ["CMD", "wget", "--no-verbose", "--tries=1", "--spider", "http://localhost:8000/health"]
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 20s

volumes:
  hermes_data:
  hermes_skills:
